var latency = () => new Promise((r) => setTimeout(r, 250 + Math.random() * 350));
function paginate(items, params = {}) {
	const page = params.page ?? 1;
	const pageSize = params.pageSize ?? 20;
	return {
		items: items.slice((page - 1) * pageSize, page * pageSize),
		total: items.length,
		page,
		pageSize
	};
}
function matches(c, q) {
	if (!q) return true;
	const s = q.toLowerCase();
	if ("phone" in c) return c.name.toLowerCase().includes(s) || c.phone.replace(/\s/g, "").includes(s.replace(/\s/g, ""));
	return c.contactName.toLowerCase().includes(s) || c.lastMessage.toLowerCase().includes(s);
}
